// CSD_RATIONALE_BEGIN
// State tracked: (generated, insideConstrainedOut, currentConstrainedOut, steps)
//   - generated: full visible output, containing free reasoning text plus << >> spans
//   - insideConstrainedOut: whether we are currently generating inside a << >> span
//   - currentConstrainedOut: the parser state for the active constrained expression
//   - steps: token-step budget consumed so far
//
// Conditions / observations used:
//   - RenderedEndsWith(generated, "<<"): detect span entry after an UnconstrainedStep
//   - parser.IsCompletePrefix(currentConstrainedOut): detect when expression is closeable
//   - AdaptiveConstrainedStep with narrowThreshold=12 and caller-supplied validTokenGroups:
//     apply group boosts only when the parser branch factor is low, giving the model
//     freedom when the grammar is wide but tighter guidance when options are few
//
// How state supports valid generation for this task:
//   - AppendTaskGuidance primes the model to follow the declared output contract
//     (step-by-step reasoning, << >> for every sub-expression and final answer)
//   - Outside spans: UnconstrainedStep lets the model produce natural reasoning prose
//   - Inside spans: AdaptiveConstrainedStep guarantees every token is parser-valid,
//     so intermediate and final symbolic expressions are syntactically correct
//   - CloseConstrainedSpan gates span closing on IsCompletePrefix, so >> is never
//     emitted over a partial/invalid expression
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Branch 1 (outside span, UnconstrainedStep):
//     If next == eosToken we break without changing span state.
//     Otherwise we append next to generated and, if RenderedEndsWith(generated,"<<"),
//     set insideConstrainedOut := true and currentConstrainedOut := []. The empty
//     prefix satisfies IsValidPrefix([]) by the method precondition.
//     If RenderedEndsWith is false, insideConstrainedOut stays false, so the
//     implication remains vacuously true.
//
//   Branch 2 (inside span, IsCompletePrefix):
//     CloseConstrainedSpan's postcondition sets insideConstrainedOut := false,
//     making the implication vacuous, and currentConstrainedOut := [] (confirmed by
//     !insideConstrainedOut ==> currentConstrainedOut == []).
//
//   Branch 3 (inside span, not yet complete):
//     AdaptiveConstrainedStep returns either eosToken (we break, no state change)
//     or a parser-valid next token. AppendConstrainedToken's postcondition asserts
//     parser.IsValidPrefix(currentConstrainedOut) after the append, preserving the
//     invariant.
//
// Invariant 2 – progress:
//   |generated| <= |generatedPrefix| + steps
//
//   Branch 1: steps += 1; we append at most one token (next, when not EOS), so
//     |generated| grows by at most 1 while steps grows by exactly 1. Bound preserved.
//
//   Branch 2: steps += 1; CloseConstrainedSpan appends at most one delimiter token
//     (">>" or nothing if the grammar already closed it), so |generated| grows by
//     at most 1. Bound preserved.
//
//   Branch 3: steps += 1; AppendConstrainedToken appends exactly one token when
//     next != eosToken, and we break without appending when next == eosToken.
//     Either way |generated| grows by at most 1. Bound preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Reason step by step. Wrap every intermediate symbolic sub-expression and the final answer in << >>. " +
  "Inside << >> use only: numbers, problem variables, and the operators +, -, /, //, %, (), int(). " +
  "Finish with: The final answer is <<expression>>.");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

